export function gymProgress(runtime){const w=runtime.world,p=runtime.progress,has=id=>p.defeatedTrainers.includes(id),count=['GYM_05_SUB_02','GYM_05_SUB_03'].filter(has).length;return'꽃가루 '+(w.interactions.includes('puzzle:5:step:1')?'관찰 완료':'미관찰')+' · 잎 뒷면 '+(w.interactions.includes('puzzle:5')?'관찰 완료':'미관찰')+' · 필수 대결 '+count+'/2 · '+(has('NPC_GYM_05_MYEONGJU')?'관장 대결 완료':'관장 대결 전')+' · 입구 농부 대결은 선택입니다.'}

// Text-only projection of the same owner state already used to draw gate 3.
export function gymObservationFeedback(snapshot){const r=snapshot.canonical,w=r.world,p=r.progress;if(!w.interactions.includes('puzzle:5'))return'꽃가루를 관찰했습니다. 위쪽 중앙의 잎 뒷면 표식을 관찰하세요.';if(snapshot.state.gymState===3)return p.defeatedTrainers.includes('NPC_GYM_05_MYEONGJU')?'두 관찰과 관장 대결을 마쳤습니다. 오른쪽 아래 입구로 돌아갈 수 있어요.':'두 관찰과 원래 선행 조건을 충족해 남쪽 관장 통로가 열렸습니다. 왼쪽 아래 단상의 명주를 만나세요.';const left=['GYM_05_SUB_02','GYM_05_SUB_03'].filter(id=>!p.defeatedTrainers.includes(id)).length;return left?'두 관찰을 마쳤습니다. 중앙 방의 자연관찰가와 왼쪽 위 조사보조원 중 남은 필수 대결 '+left+'개를 마치세요. 입구 농부 대결은 선택입니다.':'두 관찰과 필수 대결을 마쳤습니다. 관장 대결의 원래 선행 조사를 마치면 남쪽 통로가 열립니다.'}
